{"id":"ef3270ff-359f-448d-b1e4-9c3d820e0a72","inserted_at":"2026-07-03T19:39:22.080798+00:00","updated_at":"2026-07-03T19:39:22.080798+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- 0. Tabella scans (Storico delle interazioni/NFC/QR dell'utente)\r\nCREATE TABLE IF NOT EXISTS scans (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\r\n    poi_id UUID, -- Opzionale, riferimento al luogo se applicabile\r\n    validated BOOLEAN DEFAULT false,\r\n    points_earned INT DEFAULT 0,\r\n    created_at TIMESTAMPTZ DEFAULT now()\r\n);\r\n\r\n-- 1. Tabella civic_reports (versione slim, no foto obbligatoria per salvare storage)\r\nCREATE TABLE IF NOT EXISTS civic_reports (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\r\n    category TEXT NOT NULL CHECK (category IN ('barrier', 'degradation', 'lighting', 'accessibility', 'other')),\r\n    description TEXT,\r\n    latitude NUMERIC(10,8),\r\n    longitude NUMERIC(10,8),\r\n    photo_url TEXT, -- Predisposto per il futuro, ma per ora lo lasceremo NULL\r\n    status TEXT DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'rejected', 'in_progress')),\r\n    points_awarded INT DEFAULT 0,\r\n    admin_notes TEXT, -- Spazio per il moderatore\r\n    created_at TIMESTAMPTZ DEFAULT now(),\r\n    updated_at TIMESTAMPTZ DEFAULT now()\r\n);\r\n\r\n-- 2. Indici per performance\r\nCREATE INDEX IF NOT EXISTS idx_civic_reports_user ON civic_reports(user_id);\r\nCREATE INDEX IF NOT EXISTS idx_civic_reports_status ON civic_reports(status);\r\nCREATE INDEX IF NOT EXISTS idx_civic_reports_created ON civic_reports(created_at);\r\n\r\n-- 3. Trigger per aggiornare automaticamente updated_at\r\nCREATE OR REPLACE FUNCTION update_updated_at_column()\r\nRETURNS TRIGGER AS $$\r\nBEGIN\r\n    NEW.updated_at = now();\r\n    RETURN NEW;\r\nEND;\r\n$$ language 'plpgsql';\r\n\r\nDROP TRIGGER IF EXISTS update_civic_reports_updated_at ON civic_reports;\r\nCREATE TRIGGER update_civic_reports_updated_at\r\n    BEFORE UPDATE ON civic_reports\r\n    FOR EACH ROW\r\n    EXECUTE FUNCTION update_updated_at_column();\r\n\r\n-- 4. Vista leaderboard: Global Impact Score (calibrato e vivo a 30gg)\r\nCREATE OR REPLACE VIEW global_impact_leaderboard AS\r\nSELECT \r\n    p.id AS user_id,\r\n    p.nickname,\r\n    p.total_co2,\r\n    p.total_tokens,\r\n    COALESCE(c.verified_reports, 0) AS verified_reports,\r\n    COALESCE(s.validated_scans_7d, 0) AS recent_scans,\r\n    \r\n    -- Formula Calibrata\r\n    (COALESCE(s.validated_scans_7d, 0) * 1) +\r\n    (p.total_tokens * 0.1) +\r\n    (COALESCE(c.verified_reports, 0) * 5) +\r\n    (COALESCE(p.total_co2, 0) * 0.01) AS impact_score,\r\n    \r\n    -- Rank calcolato dinamicamente\r\n    ROW_NUMBER() OVER (ORDER BY \r\n        (COALESCE(s.validated_scans_7d, 0) * 1) +\r\n        (p.total_tokens * 0.1) +\r\n        (COALESCE(c.verified_reports, 0) * 5) +\r\n        (COALESCE(p.total_co2, 0) * 0.01) DESC\r\n    ) AS rank\r\n\r\nFROM profiles p\r\nLEFT JOIN (\r\n    SELECT user_id, COUNT(id) AS verified_reports\r\n    FROM civic_reports\r\n    WHERE status = 'verified'\r\n    GROUP BY user_id\r\n) c ON p.id = c.user_id\r\nLEFT JOIN (\r\n    SELECT user_id, COUNT(id) AS validated_scans_7d\r\n    FROM scans\r\n    WHERE validated = true\r\n      AND created_at > now() - interval '7 days'\r\n    GROUP BY user_id\r\n) s ON p.id = s.user_id\r\n\r\nORDER BY impact_score DESC;\r\n\r\n-- 5. Vista per pannello Admin (Segnalazioni da moderare)\r\nCREATE OR REPLACE VIEW civic_reports_pending AS\r\nSELECT \r\n    cr.*,\r\n    p.nickname,\r\n    p.total_tokens\r\nFROM civic_reports cr\r\nJOIN profiles p ON cr.user_id = p.id\r\nWHERE cr.status = 'pending'\r\nORDER BY cr.created_at DESC;\r\n\r\n-- 6. Row Level Security (RLS) base per civic_reports\r\nALTER TABLE civic_reports ENABLE ROW LEVEL SECURITY;\r\n\r\n-- Gli utenti possono leggere le PROPRIE segnalazioni\r\nCREATE POLICY \"Users can read own reports\" \r\nON civic_reports FOR SELECT \r\nUSING (auth.uid() = user_id);\r\n\r\n-- Gli utenti possono INSERIRE le proprie segnalazioni\r\nCREATE POLICY \"Users can insert own reports\" \r\nON civic_reports FOR INSERT \r\nWITH CHECK (auth.uid() = user_id);\r\n\r\n-- (Gli admin B2B avranno accesso tramite service_role key nel backend o policy apposite in futuro)","content_id":"ef3270ff-359f-448d-b1e4-9c3d820e0a72","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
